60	std::string GetNetworkName(enum Network net)
61	{
62	    switch (net) {
63	    case NET_UNROUTABLE: return "not_publicly_routable";
64	    case NET_IPV4: return "ipv4";
65	    case NET_IPV6: return "ipv6";
66	    case NET_ONION: return "onion";
67	    case NET_I2P: return "i2p";
68	    case NET_CJDNS: return "cjdns";
69	    case NET_INTERNAL: return "internal";
70	    case NET_MAX: assert(false);
71	    } // no default case, so the compiler can warn about missing cases
72	
73	    assert(false);
74	}
