90	bool static LookupIntern(const std::string& name, std::vector<CNetAddr>& vIP, unsigned int nMaxSolutions, bool fAllowLookup)
91	{
92	    vIP.clear();
93	
94	    if (!ValidAsCString(name)) {
95	        return false;
96	    }
97	
98	    {
99	        CNetAddr addr;
100	        // From our perspective, onion addresses are not hostnames but rather
101	        // direct encodings of CNetAddr much like IPv4 dotted-decimal notation
102	        // or IPv6 colon-separated hextet notation. Since we can't use
103	        // getaddrinfo to decode them and it wouldn't make sense to resolve
104	        // them, we return a network address representing it instead. See
105	        // CNetAddr::SetSpecial(const std::string&) for more details.
106	        if (addr.SetSpecial(name)) {
107	            vIP.push_back(addr);
108	            return true;
109	        }
110	    }
111	
112	    struct addrinfo aiHint;
113	    memset(&aiHint, 0, sizeof(struct addrinfo));
114	
115	    // We want a TCP port, which is a streaming socket type
116	    aiHint.ai_socktype = SOCK_STREAM;
117	    aiHint.ai_protocol = IPPROTO_TCP;
118	    // We don't care which address family (IPv4 or IPv6) is returned
119	    aiHint.ai_family = AF_UNSPEC;
120	    // If we allow lookups of hostnames, use the AI_ADDRCONFIG flag to only
121	    // return addresses whose family we have an address configured for.
122	    //
123	    // If we don't allow lookups, then use the AI_NUMERICHOST flag for
124	    // getaddrinfo to only decode numerical network addresses and suppress
125	    // hostname lookups.
126	    aiHint.ai_flags = fAllowLookup ? AI_ADDRCONFIG : AI_NUMERICHOST;
127	    struct addrinfo *aiRes = nullptr;
128	    int nErr = getaddrinfo(name.c_str(), nullptr, &aiHint, &aiRes);
129	    if (nErr)
130	        return false;
131	
132	    // Traverse the linked list starting with aiTrav, add all non-internal
133	    // IPv4,v6 addresses to vIP while respecting nMaxSolutions.
134	    struct addrinfo *aiTrav = aiRes;
135	    while (aiTrav != nullptr && (nMaxSolutions == 0 || vIP.size() < nMaxSolutions))
136	    {
137	        CNetAddr resolved;
138	        if (aiTrav->ai_family == AF_INET)
139	        {
140	            assert(aiTrav->ai_addrlen >= sizeof(sockaddr_in));
141	            resolved = CNetAddr(((struct sockaddr_in*)(aiTrav->ai_addr))->sin_addr);
142	        }
143	
144	        if (aiTrav->ai_family == AF_INET6)
145	        {
146	            assert(aiTrav->ai_addrlen >= sizeof(sockaddr_in6));
147	            struct sockaddr_in6* s6 = (struct sockaddr_in6*) aiTrav->ai_addr;
148	            resolved = CNetAddr(s6->sin6_addr, s6->sin6_scope_id);
149	        }
150	        /* Never allow resolving to an internal address. Consider any such result invalid */
151	        if (!resolved.IsInternal()) {
152	            vIP.push_back(resolved);
153	        }
154	
155	        aiTrav = aiTrav->ai_next;
156	    }
157	
158	    freeaddrinfo(aiRes);
159	
160	    return (vIP.size() > 0);
161	}
